# 1. 用正则表达式提取所有浮点数（形如 -1.2345e-01）
nums = [float(x) for x in re.findall(r'[-+]?\d+\.\d+e[+-]?\d+', raw)]

# 2. 转成 PyTorch tensor，并按照 8 列 reshape
tensor = torch.tensor(nums).view(-1, 8)

print("tensor 形状:", tensor.shape)
print("tensor 前几行:\n", tensor[:5])

# 3. 计算所有元素的平均值
mean_value = tensor.mean()
print("tensor 的平均值:", mean_value.item())

# ===== 你要的新部分从这里开始 =====

# 4. 每 8 个的均值（每一行的均值）
group_means = tensor.mean(dim=1)  # 形状: [num_groups]
# 这些均值之间的方差
var_of_group_means = group_means.var(unbiased=False)  # 设置为总体方差，可按需要改

print("每 8 个的均值的方差:", var_of_group_means.item())

# 5. 每个组内（每一行）的方差
group_vars = tensor.var(dim=1, unbiased=False)  # 每行自己的方差
# 这些组内方差的平均值
mean_of_group_vars = group_vars.mean()

print("每个组内方差的均值:", mean_of_group_vars.item())
